82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
110	        owner.setTelephone(telephone);
111	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
112	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
113	        if (owner.getRegistrationDate() == null) {
114	            owner.setRegistrationDate(LocalDate.now());
115	        }
116	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
117	            .anyMatch(existing -> telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone())));
118	        if (telephoneInUse) {
119	            throw new DuplicateTelephoneException(
120	                "telephone " + telephone + " is already used by another owner");
121	        }
122	        this.clinicService.createOwner(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
132	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
133	        if (currentOwner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        currentOwner.setAddress(ownerFieldsDto.getAddress());
137	        currentOwner.setCity(ownerFieldsDto.getCity());
138	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
139	        currentOwner.setLastName(ownerFieldsDto.getLastName());
140	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
141	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
142	        this.clinicService.saveOwner(currentOwner);
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
144	    }
